<?php require_once __DIR__ . '/../includes/config.php'; require_once __DIR__ . '/../includes/auth.php'; require_login();
$format=$_GET['format']??'csv';
$rows=$pdo->query('SELECT bc.id,bc.complaint_date,bc.complainer_name,COALESCE(s.name,"") student,COALESCE(bc.class_name,"") class,COALESCE(bc.administrator_name,"") administrator,COALESCE(bc.relationship_text,"") relationship,COALESCE(bc.complaint_text,"") complain,bc.complaint_main_type,bc.complaint_type,b.name bus,bc.route,bc.driver_name,bc.matron_name,bc.status,bc.procedure_note,COALESCE(bc.communication_type,"") communication_type,COALESCE(bc.responsible_name,"") responsible_name,bc.students_involved_count FROM bus_complaints bc JOIN buses b ON b.id=bc.bus_id LEFT JOIN students s ON s.id=bc.student_id ORDER BY bc.id DESC')->fetchAll();
if($format==='csv'){ header('Content-Type: text/csv; charset=UTF-8'); header('Content-Disposition: attachment; filename="complains.csv"'); echo "\xEF\xBB\xBF"; $o=fopen('php://output','w'); if($rows) fputcsv($o,array_keys($rows[0])); foreach($rows as $r) fputcsv($o,$r); fclose($o); exit; }
header('Content-Type: text/html; charset=UTF-8'); echo '<!doctype html><html lang="ar" dir="rtl"><meta charset="utf-8"><style>body{font-family:Tahoma,Arial}table{width:100%;border-collapse:collapse}th,td{border:1px solid #444;padding:6px}</style><h2>Complain Report</h2><table>'; if($rows){ echo '<tr>'; foreach(array_keys($rows[0]) as $h) echo '<th>'.h($h).'</th>'; echo '</tr>'; foreach($rows as $r){ echo '<tr>'; foreach($r as $v) echo '<td>'.h((string)$v).'</td>'; echo '</tr>';}} echo '</table><script>window.print()</script></html>';
